import { NextResponse, type NextRequest } from "next/server";
import { getServerSupabase, getServiceSupabase, requireAdmin } from "@/lib/supabase/server";
import { supabaseEnabled } from "@/lib/supabase/config";
import { encryptSecret, encryptionRequiredButMissing } from "@/lib/crypto-secrets";
import { PUBLIC_DEMO_DRY_RUN_DETAIL, publicDemoSideEffectsDisabled } from "@/lib/server/demo-side-effects";

/**
 * Google OAuth callback for Gmail API seat connection.
 *
 * Exchanges the authorization code for tokens, stores them in
 * public.email_connections, updates the seat's connected_account, and redirects
 * back to Settings → Fleet with a toast.
 */
export async function GET(req: NextRequest) {
  const clientId = process.env.GOOGLE_CLIENT_ID;
  const clientSecret = process.env.GOOGLE_CLIENT_SECRET;
  if (!clientId || !clientSecret) {
    return redirectError(req, "Google OAuth is not configured.");
  }

  const searchParams = new URL(req.url).searchParams;
  const code = searchParams.get("code");
  const error = searchParams.get("error");
  const stateParam = searchParams.get("state");

  if (error) {
    return redirectError(req, `Google OAuth error: ${error}`);
  }
  if (!code || !stateParam) {
    return redirectError(req, "Missing authorization code or state.");
  }

  let state: { seatId?: string; provider?: string; nonce?: string };
  try {
    state = JSON.parse(Buffer.from(stateParam, "base64url").toString("utf-8"));
  } catch {
    return redirectError(req, "Invalid OAuth state.");
  }
  const seatId = state.seatId;
  if (!seatId) {
    return redirectError(req, "Missing seat id in OAuth state.");
  }

  // CSRF: the state nonce must match the value bound to this browser at start.
  const cookieNonce = req.cookies.get(STATE_COOKIE)?.value;
  if (!state.nonce || !cookieNonce || !safeEqual(state.nonce, cookieNonce)) {
    return redirectError(req, "OAuth state mismatch.");
  }
  // PKCE: the verifier proves this is the same browser that began the flow.
  const codeVerifier = req.cookies.get(VERIFIER_COOKIE)?.value;
  if (!codeVerifier) {
    return redirectError(req, "Missing PKCE verifier.");
  }

  if (!supabaseEnabled) {
    return redirectError(req, "Email connections require Supabase (live mode).");
  }

  // Fail closed: never persist a new OAuth mailbox token in cleartext when
  // production requires encryption at rest but DATA_ENCRYPTION_KEY isn't configured.
  if (encryptionRequiredButMissing()) {
    return redirectError(req, "Server encryption key is not configured.");
  }

  const supabase = await getServerSupabase();
  const svc = getServiceSupabase();
  if (!supabase || !svc) {
    return redirectError(req, "Supabase not configured.");
  }

  const admin = await requireAdmin(supabase);
  if (!admin.ok) return admin.response;
  if (publicDemoSideEffectsDisabled()) {
    return redirectError(req, PUBLIC_DEMO_DRY_RUN_DETAIL);
  }

  const redirectUri = process.env.GOOGLE_REDIRECT_URI ?? "http://localhost:3000/auth/google/callback";

  // Exchange code for tokens (PKCE verifier proves possession; 10s timeout).
  let tokenRes: Response;
  try {
    tokenRes = await fetchWithTimeout("https://oauth2.googleapis.com/token", {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({
        code,
        client_id: clientId,
        client_secret: clientSecret,
        redirect_uri: redirectUri,
        grant_type: "authorization_code",
        code_verifier: codeVerifier,
      }),
    });
  } catch {
    return redirectError(req, "Google token exchange timed out.");
  }
  const tokenJson = (await tokenRes.json().catch(() => ({}))) as {
    access_token?: string;
    refresh_token?: string;
    expires_in?: number;
    scope?: string;
    error?: string;
    error_description?: string;
  };
  if (!tokenRes.ok || !tokenJson.access_token) {
    return redirectError(req, tokenJson.error_description ?? tokenJson.error ?? "Google token exchange failed.");
  }

  // Fetch account email from Gmail profile (or use tokeninfo as fallback).
  let profileRes: Response;
  try {
    profileRes = await fetchWithTimeout("https://www.googleapis.com/gmail/v1/users/me/profile", {
      headers: { Authorization: `Bearer ${tokenJson.access_token}` },
    });
  } catch {
    return redirectError(req, "Could not retrieve Gmail account email.");
  }
  const profile = (await profileRes.json().catch(() => ({}))) as { emailAddress?: string };
  const accountEmail = profile.emailAddress ?? "";
  if (!accountEmail) {
    return redirectError(req, "Could not retrieve Gmail account email.");
  }

  const { data: wid } = await supabase.rpc("current_workspace_id");
  // Cross-tenant guard: the seat must belong to the caller's workspace before any
  // service-role write (the service-role client bypasses RLS).
  const { data: seatRow } = await svc.from("agent_seats").select("workspace_id").eq("id", seatId).single();
  if (!seatRow || seatRow.workspace_id !== wid) {
    return redirectError(req, "Seat is not in your workspace.");
  }
  const expiresAt = tokenJson.expires_in
    ? new Date(Date.now() + tokenJson.expires_in * 1000).toISOString()
    : null;

  // Upsert connection.
  const { error: upsertError } = await svc.from("email_connections").upsert(
    {
      workspace_id: wid,
      seat_id: seatId,
      provider: "Gmail API",
      account_email: accountEmail,
      access_token: encryptSecret(tokenJson.access_token),
      refresh_token: tokenJson.refresh_token ? encryptSecret(tokenJson.refresh_token) : null,
      expires_at: expiresAt,
      scope: tokenJson.scope ?? "https://www.googleapis.com/auth/gmail.send https://www.googleapis.com/auth/gmail.readonly",
      updated_at: new Date().toISOString(),
    },
    { onConflict: "workspace_id, seat_id" },
  );
  if (upsertError) {
    console.error("[google/callback] email_connections upsert failed:", upsertError.message, upsertError.code);
    return redirectError(req, "Failed to save email connection.");
  }

  // Mirror connected account on the seat.
  const { error: updateError } = await svc.from("agent_seats").update({ connected_account: accountEmail }).eq("id", seatId);
  if (updateError) {
    console.error("[google/callback] agent_seats update failed:", updateError.message, updateError.code);
    return redirectError(req, "Failed to update seat connection.");
  }

  return redirectSuccess(req, `Connected ${accountEmail}`);
}

/** Cookie names binding the OAuth `state` nonce and PKCE verifier to this browser. */
const STATE_COOKIE = "g_oauth_state";
const VERIFIER_COOKIE = "g_oauth_verifier";

/** `fetch` with a hard abort deadline so a hung provider cannot stall the route. */
async function fetchWithTimeout(input: string, init: RequestInit, timeoutMs = 10_000): Promise<Response> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await fetch(input, { ...init, signal: controller.signal });
  } finally {
    clearTimeout(timer);
  }
}

/** Constant-time string compare to avoid leaking the nonce via timing. */
function safeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

/** Expire the single-use state/verifier cookies on every callback exit. */
function clearOAuthCookies(res: NextResponse): void {
  res.cookies.set(STATE_COOKIE, "", { path: "/", maxAge: 0 });
  res.cookies.set(VERIFIER_COOKIE, "", { path: "/", maxAge: 0 });
}

function redirectError(req: NextRequest, message: string) {
  const encoded = encodeURIComponent(message);
  const res = NextResponse.redirect(new URL(`/settings?tab=fleet&oauth=error&message=${encoded}`, req.url));
  clearOAuthCookies(res);
  return res;
}

function redirectSuccess(req: NextRequest, message: string) {
  const encoded = encodeURIComponent(message);
  const res = NextResponse.redirect(new URL(`/settings?tab=fleet&oauth=success&message=${encoded}`, req.url));
  clearOAuthCookies(res);
  return res;
}

import { NextResponse, type NextRequest } from "next/server";
import { getServerSupabase, requireAdmin } from "@/lib/supabase/server";
import { PUBLIC_DEMO_DRY_RUN_DETAIL, publicDemoSideEffectsDisabled } from "@/lib/server/demo-side-effects";

// Auth-gated, never cacheable — and without this, Next tries to prerender the
// route at build time (calling requireAdmin() before it touches any request
// API Next would otherwise auto-detect as dynamic), which throws the
// production fail-closed guard as a build error when Supabase isn't configured.
export const dynamic = "force-dynamic";

/**
 * Start Google OAuth for a Gmail API seat.
 *
 * Query params:
 *   seat_id  — the agent_seat.id to connect
 *
 * Required env:
 *   GOOGLE_CLIENT_ID
 *   GOOGLE_REDIRECT_URI (defaults to http://localhost:3000/auth/google/callback)
 */
export async function GET(req: NextRequest) {
  // Only an authenticated admin may initiate an OAuth seat connection.
  const admin = await requireAdmin(await getServerSupabase());
  if (!admin.ok) return admin.response;

  const clientId = process.env.GOOGLE_CLIENT_ID;
  if (!clientId) {
    return NextResponse.json({ ok: false, error: "Google OAuth is not configured." }, { status: 500 });
  }

  const searchParams = new URL(req.url).searchParams;
  const seatId = searchParams.get("seat_id");
  if (!seatId) {
    return NextResponse.json({ ok: false, error: "Missing seat_id." }, { status: 400 });
  }

  if (publicDemoSideEffectsDisabled()) {
    return NextResponse.json({ ok: false, status: "dry-run", error: PUBLIC_DEMO_DRY_RUN_DETAIL }, { status: 403 });
  }

  const redirectUri = process.env.GOOGLE_REDIRECT_URI ?? "http://localhost:3000/auth/google/callback";

  // CSRF: random nonce echoed in `state` and bound to an HttpOnly cookie, verified
  // in the callback. PKCE (S256): a high-entropy verifier kept server-side (cookie)
  // with only its SHA-256 challenge sent to Google, so a stolen code is useless.
  const nonce = randomToken(16);
  const codeVerifier = randomToken(32);
  const codeChallenge = await pkceChallenge(codeVerifier);
  const state = Buffer.from(JSON.stringify({ seatId, provider: "Gmail API", nonce })).toString("base64url");

  const authUrl = new URL("https://accounts.google.com/o/oauth2/v2/auth");
  authUrl.searchParams.set("client_id", clientId);
  authUrl.searchParams.set("redirect_uri", redirectUri);
  authUrl.searchParams.set("response_type", "code");
  authUrl.searchParams.set("scope", "https://www.googleapis.com/auth/gmail.send https://www.googleapis.com/auth/gmail.readonly https://www.googleapis.com/auth/calendar.events");
  authUrl.searchParams.set("access_type", "offline");
  authUrl.searchParams.set("prompt", "consent");
  authUrl.searchParams.set("state", state);
  authUrl.searchParams.set("code_challenge", codeChallenge);
  authUrl.searchParams.set("code_challenge_method", "S256");

  const res = NextResponse.redirect(authUrl.toString());
  const isHttps = req.nextUrl.protocol === "https:" || req.headers.get("x-forwarded-proto") === "https";
  const isLocalhost = req.nextUrl.hostname === "localhost" || req.nextUrl.hostname === "127.0.0.1";
  const secureCookie = isHttps || !isLocalhost;
  const cookieOpts = {
    httpOnly: true,
    secure: secureCookie,
    sameSite: "lax" as const,
    path: "/",
    maxAge: 600,
  };
  res.cookies.set(STATE_COOKIE, nonce, cookieOpts);
  res.cookies.set(VERIFIER_COOKIE, codeVerifier, cookieOpts);
  return res;
}

/** Cookie names binding the OAuth `state` nonce and PKCE verifier to this browser. */
const STATE_COOKIE = "g_oauth_state";
const VERIFIER_COOKIE = "g_oauth_verifier";

/** URL-safe random token from `bytes` of CSPRNG entropy (Web Crypto). */
function randomToken(bytes: number): string {
  return Buffer.from(crypto.getRandomValues(new Uint8Array(bytes))).toString("base64url");
}

/** PKCE S256 challenge: base64url( SHA-256( verifier ) ). */
async function pkceChallenge(verifier: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(verifier));
  return Buffer.from(new Uint8Array(digest)).toString("base64url");
}

import { createServerClient, type CookieOptions } from "@supabase/ssr";
import { createClient } from "@supabase/supabase-js";
import { cookies } from "next/headers";
import { NextResponse } from "next/server";
import {
  SUPABASE_ANON_KEY,
  SUPABASE_AUTH_COOKIE_NAME,
  SUPABASE_SERVICE_ROLE_KEY,
  SUPABASE_URL,
  supabaseEnabled,
  isProduction,
  demoLoginEnabled,
  assertSupabaseConfiguredInProd,
} from "./config";

type CookieToSet = { name: string; value: string; options?: CookieOptions };

export type AdminCheckResult =
  | { ok: true; role: string }
  | { ok: false; response: NextResponse };

/**
 * Server-side admin guard. Requires an authenticated session and role = 'admin'.
 * In non-production DEMO mode (no Supabase) the check is skipped and returns
 * ok=true. In production with no Supabase it FAILS CLOSED (503) — never ok=true.
 * Use this in mutating API routes that should be admin-only.
 */
export async function requireAdmin(
  serverSupabase: Awaited<ReturnType<typeof getServerSupabase>>,
): Promise<AdminCheckResult> {
  if (!supabaseEnabled || !serverSupabase) {
    // Fail CLOSED in production: without a verified Supabase session we cannot
    // confirm identity or role, so admin access must NEVER be granted. DEMO mode
    // (non-production) stays open for local development, as does a deliberately
    // public synthetic demo (NEXT_PUBLIC_ENABLE_DEMO_LOGIN=true) whose state is
    // entirely in-browser anyway.
    if (isProduction && !demoLoginEnabled) {
      return {
        ok: false,
        response: NextResponse.json(
          { ok: false, error: "Server authentication is not configured." },
          { status: 503 },
        ),
      };
    }
    return { ok: true, role: "admin" };
  }
  const {
    data: { user },
    error: userErr,
  } = await serverSupabase.auth.getUser();
  if (userErr || !user) {
    return { ok: false, response: NextResponse.json({ ok: false, error: "Not authenticated." }, { status: 401 }) };
  }
  const { data: role, error: roleErr } = await serverSupabase.rpc("current_profile_role");
  if (roleErr || role !== "admin") {
    return { ok: false, response: NextResponse.json({ ok: false, error: "Admins only." }, { status: 403 }) };
  }
  return { ok: true, role };
}

/**
 * Service-role client (SERVER ONLY) — bypasses RLS to read secrets (e.g. API key
 * values) for server-side validation. Never import this into a client component.
 */
export function getServiceSupabase() {
  // Fail closed in production: a missing Supabase env must not be silently
  // tolerated here either (a legitimately-absent service-role key still returns
  // null below, which callers already handle).
  assertSupabaseConfiguredInProd();
  if (!supabaseEnabled || !SUPABASE_SERVICE_ROLE_KEY) return null;
  return createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
}

/**
 * Server Supabase client bound to the request cookies. Use in Server Components,
 * Route Handlers, and middleware. Returns null in DEMO mode.
 */
export async function getServerSupabase() {
  // Fail closed in production: never hand back a null (DEMO/admin) request context
  // when Supabase env is missing — that is the fail-open bug this guard prevents.
  assertSupabaseConfiguredInProd();
  if (!supabaseEnabled) return null;
  // Next.js 15+: cookies() is async-only.
  const cookieStore = await cookies();
  return createServerClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
    cookieOptions: { name: SUPABASE_AUTH_COOKIE_NAME },
    cookies: {
      getAll() {
        return cookieStore.getAll();
      },
      setAll(cookiesToSet: CookieToSet[]) {
        try {
          cookiesToSet.forEach(({ name, value, options }) =>
            cookieStore.set(name, value, options),
          );
        } catch {
          // called from a Server Component — middleware refreshes the session instead
        }
      },
    },
  });
}

